 async function photo(file){if(!file)return;stopCamera();const generation=cameraGeneration;if(!file.type.startsWith('image/'))throw Error('Selecciona una imagen del código de barras.');if(file.size>15*1024*1024)throw Error('Usa una imagen de menos de 15 MB.');cameraFrame('loading','Leyendo el código de la foto…',{action:'stop'});cameraStatus('Leyendo el código de la foto…');const reader=await window.QuipuBarcode.createMobileReader({loadScript});if(generation!==cameraGeneration)return;const result=await reader.decodeFile(file);if(generation!==cameraGeneration)return;if(!result)throw Error('No se pudo leer un código válido en la foto. Incluye todas las barras, sin reflejos y con buena nitidez.');await scan(result.getText());}
 async function submit(form){if(orderBusy)throw Error('Espera a que termine el registro de la venta.');const type=form.dataset.qpForm,values=Object.fromEntries(new FormData(form));if(type==='email-login'){const session=await api('auth/google',{data:{email:values.email}});user=session.user;csrf=session.csrf;admin=session.isAdmin;await loadBusinesses();return;}if(type==='products'){stopCamera();productBarcodeTarget=null;}if(type==='scan')return scan(values.barcode);if(type==='checkout-sale')return checkoutSale();if(type==='cart-add'){const product=snapshot.products.find(p=>p.id===values.productId);if(!product)throw Error('Selecciona un producto.');cart().rows=window.QuipuCart.add(cart().rows,product,Number(values.quantity));cart().key=null;renderOrder();return;}if(type==='report')return showReport(values.period,values.date);
 if(type==='business'){
  if(!canRegisterBusiness||businesses.length){await loadBusinesses();notice('Tu cuenta ya tiene una bodega registrada. Continúa con ella.',true);return;}
  try{const result=await api('businesses',{data:{name:values.name}});selected=result.id;await loadBusinesses();}
  catch(error){if(error.code==='single_business_per_account'){await loadBusinesses();notice(error.message,true);return;}throw error;}
  return;
 }
 const data={...values};if(type==='products')Object.assign(data,{costCents:price(values.cost),priceCents:price(values.price),stock:Number(values.stock),minimum:Number(values.minimum)});if(type==='stock')data.delta=Number(values.delta);if(type==='sales')Object.assign(data,{items:[{productId:values.productId,quantity:Number(values.quantity)}]});if(type==='expenses'||type==='receivables')data.amountCents=price(values.amount);if(type==='suppliers')Object.assign(data,{deliveryCents:price(values.delivery),leadDays:Number(values.leadDays)});if(type==='offers')Object.assign(data,{priceCents:price(values.price),minimum:Number(values.minimum)});if(type==='purchases')data.items=[{productId:values.productId,quantity:Number(values.quantity),costCents:price(values.cost)}];if(type==='cash')for(const x of ['cash','yape','plin','card'])data[x]=price(values[x]);
 // Retain the same request key after a connection failure; an edited form gets a new one.
 const signature=JSON.stringify({type,data});if(!pendingKey||pendingKey.signature!==signature)pendingKey={signature,key:crypto.randomUUID()};await api(endpoint(type),{data,key:pendingKey.key});pendingKey=null;await loadSnapshot();notice('Guardado en tu bodega.');}
 function adminDenied(){stopCamera();document.body.classList.remove('qp-crm-mode','qp-menu-open');root.innerHTML='<section class="qa-card qa-access"><span class="bs-eyebrow">ACCESO RESTRINGIDO</span><h1>Esta cuenta no es administradora.</h1><p>Inicia sesión con la cuenta de Google autorizada para administrar Quipu.</p><p class="qa-muted">Cuenta actual: '+esc(user?.email)+'</p><p data-qp-notice role="alert" hidden></p>'+button('Cerrar sesión y usar otra cuenta','data-qp-logout')+'<p><a href="#gestion">Ir a mi negocio →</a></p></section>';}
