  if(element.hasAttribute('data-qp-local-login')){const session=await api('auth/google',{data:{}});user=session.user;csrf=session.csrf;admin=session.isAdmin;await loadBusinesses();return;}
  if(element.dataset.qpQuickAdd){if(orderBusy)return;const product=snapshot?.products.find(p=>p.id===element.dataset.qpQuickAdd);if(!product)return;cart().rows=window.QuipuCart.add(cart().rows,product,1);cart().key=null;renderOrder();const status=root.querySelector('[data-qp-cart-status]');if(status)status.textContent=`✓ ${product.name} añadido al pedido.`;return;}
  if(element.dataset.qpPosCat){const cat=element.dataset.qpPosCat;root.querySelectorAll('[data-qp-pos-cat]').forEach(b=>b.classList.toggle('active',b.dataset.qpPosCat===cat));const q=(root.querySelector('[data-qp-pos-search]')?.value||'').trim().toLowerCase();root.querySelectorAll('[data-qp-quick-add]').forEach(tile=>{const matchCat=cat==='Todas'||tile.dataset.cat===cat;const matchQ=!q||tile.dataset.search.includes(q);tile.hidden=!(matchCat&&matchQ);});return;}
  if(element.dataset.qpStockDelta){const delta=Number(element.dataset.qpStockDelta),productId=element.dataset.qpProd;await api(endpoint('stock'),{data:{productId,delta},key:crypto.randomUUID()});await loadSnapshot();notice(`Existencias actualizadas (${delta>0?'+1':'-1'}).`);return;}
  if(element.hasAttribute('data-qp-cart-clear')){if(orderBusy)return;cart().rows=[];cart().key=null;renderOrder();}else if(element.dataset.qpCartRemove){if(orderBusy)return;cart().rows=cart().rows.filter(x=>x.product.id!==element.dataset.qpCartRemove);cart().key=null;renderOrder();}else if(element.hasAttribute('data-qp-menu')){const open=document.body.classList.toggle('qp-menu-open');element.setAttribute('aria-expanded',String(open));}else if(element.hasAttribute('data-qp-refresh')){await loadBusinesses();notice('Tus datos están actualizados.');}else if(element.dataset.qpFilter){alertFilter=element.dataset.qpFilter;await renderView();}else if(element.dataset.qpReview){await api(endpoint('alert-review'),{data:{key:element.dataset.qpReview}});snapshot.alertReviews.push({alert_key:element.dataset.qpReview});await renderView();}else if(element.hasAttribute('data-qp-trial')){await api(endpoint('trial'),{data:{}});await loadBusinesses();notice('Tu prueba gratuita de 7 días está activa. ¡Bienvenido!');}else if(element.dataset.qpEdit){const product=snapshot.products.find(x=>x.id===element.dataset.qpEdit);if(!product)return;const form=root.querySelector('[data-qp-form="products"]');for(const [key,value]of Object.entries({name:product.name,category:product.category,cost:(product.unit_cost_micros/1000000).toFixed(2),price:(product.sale_price_cents/100).toFixed(2),stock:product.stock,minimum:product.minimum_stock,expiry:product.expiry_date||'',barcode:product.barcode||''}))form.elements[key].value=value;let id=form.elements.productId;if(!id){id=document.createElement('input');id.type='hidden';id.name='productId';form.append(id);}id.value=product.id;form.elements.stock.readOnly=true;form.querySelector('button[type="submit"],button:not([type])').textContent='Guardar cambios';form.scrollIntoView({block:'center'});}else if(element.hasAttribute('data-qp-retry'))await mountAgain();
  else if(element.dataset.qpView){view=element.dataset.qpView;document.body.classList.remove('qp-menu-open');shell();await renderView();}
  else if(element.dataset.qpShop){selected=element.dataset.qpShop;await loadBusinesses();}
  else if(element.hasAttribute('data-qp-logout')){await api('auth/logout',{data:{}});window.google?.accounts?.id?.disableAutoSelect();orders.clear();user=null;csrf='';admin=false;snapshot=null;selected='';dataRevision++;stopCamera();document.body.classList.remove('qp-crm-mode','qp-menu-open');await login();}
  else if(element.dataset.qpCheckout){const signature='checkout|'+selected+'|'+element.dataset.qpCheckout;if(!pendingKey||pendingKey.signature!==signature)pendingKey={signature,key:crypto.randomUUID()};const result=await api(endpoint('checkout'),{data:{months:Number(element.dataset.qpCheckout)},key:pendingKey.key});sessionStorage.setItem('quipu-checkout',result.checkoutId);location.assign(result.url);}
  else if(element.dataset.qpReceive){await api(endpoint('receive'),{data:{orderId:element.dataset.qpReceive},key:crypto.randomUUID()});await loadSnapshot();notice('Pedido recibido. Existencias y costo actualizados.');}
  else if(element.hasAttribute('data-qp-pdf'))await pdf();
  else if(element.hasAttribute('data-qp-camera-light')){try{const enabled=element.getAttribute('aria-pressed')!=='true';if(await adjustCamera('torch',enabled)){element.setAttribute('aria-pressed',String(enabled));element.textContent=enabled?'Apagar luz':'Encender luz';}}catch(error){cameraStatus(error.message,true);}}
  else if(element.hasAttribute('data-qp-camera-focus')){try{if(await adjustCamera('focusMode'))cameraStatus('Enfoque solicitado. Mantén las barras nítidas dentro del recuadro.');}catch(error){cameraStatus(error.message,true);}}
  else if(element.hasAttribute('data-qp-camera-flip')){const devices=(await navigator.mediaDevices.enumerateDevices()).filter(x=>x.kind==='videoinput');if(devices.length<2)throw Error('Solo hay una cámara disponible.');const current=stream?.getVideoTracks()[0]?.getSettings().deviceId,index=devices.findIndex(x=>x.deviceId===current);await camera(devices[(index+1)%devices.length].deviceId);}else if(element.hasAttribute('data-qp-camera-start'))await camera();
