 document.addEventListener('change',async e=>{if(e.target.matches('[data-qp-camera-zoom]')){try{if(await adjustCamera('zoom',Number(e.target.value))){const output=root.querySelector('[data-qp-zoom-value]');if(output)output.textContent=Number(e.target.value).toFixed(1)+'×';}}catch(error){cameraStatus(error.message,true);}return;}if(e.target.matches('[data-qp-barcode-photo]')){try{await photo(e.target.files?.[0]);}catch(error){cameraFrame('error',error.message,{error:true,label:'Activar cámara'});cameraStatus(error.message,true);notice(error.message,true);}finally{e.target.value='';}return;}if(e.target.matches('[data-qp-cart-qty]')){try{if(orderBusy)throw Error('Espera a que termine el registro.');cart().rows=window.QuipuCart.set(cart().rows,e.target.dataset.qpCartQty,Number(e.target.value));cart().key=null;renderOrder();}catch(error){notice(error.message,true);renderOrder();}return;}if(e.target.closest('[data-qp-form="checkout-sale"]')){if(orderBusy)return;const form=e.target.closest('form');cart().method=form.elements.method.value;cart().customerId=form.elements.customerId.value;cart().key=null;updatePayment();return;}if(e.target.matches('[data-qp-shop-select]')){selected=e.target.value;await loadBusinesses();}if(e.target.closest('[data-qp-form="sales"]')){const form=e.target.closest('form'),product=snapshot?.products.find(x=>x.id===form.elements.productId.value),output=form.querySelector('[data-qp-sale-total]');if(output)output.textContent=product?'Total: '+money(product.sale_price_cents*Number(form.elements.quantity.value)):'Selecciona un producto';}});
